//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME: 		HE_FrekvOmf_Vacon100_Wrapper                                                                                                                                                                                                                                                                     
//	CREATOR:		JMD                                                                                                                                                                                                                                            
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE					SIGN				DESCRIPTION                                                                                                                                                                                                                                 
//  2.0					31.01.2025			JMD					Draft
//===============================================================================================================================
//
//		DESCRIPTION:
//
//
//===============================================================================================================================

(*************************************************************************
 *	Update  Input
 *************************************************************************)
 
// Task interval
Wrk_IntervalSec := LINT_TO_REAL(TimeToNanoSec(In:=GetMyTaskInterval())) / 1e9;

 // Config Parameter
Ext_VFD.EXT_Engineering.Auto_Visible:= 						Cfg_Auto_InUse;
Ext_VFD.EXT_General.LocationIndex[0]:=						Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_VFD.EXT_Engineering.ReverseRunning_Visible:=		FALSE;
Ext_VFD.EXT_Engineering.LCfg_Autotune_Visible:=		FALSE;
Ext_VFD.EXT_Engineering.LCfg_MotorData_Visible:=		FALSE;
Ext_VFD.EXT_Engineering.LCfg_RampTime_Visible:=		FALSE;

// Input Parmeter
FB_VFD_Logic.Cfg_ControllerTAG:=				Cfg_ControllerName;
FB_VFD_Logic.Cfg_ProcessTAG:=					Cfg_ProcessTAG;
FB_VFD_Logic.Inp_STO:=								Inp_Estop;
FB_VFD_Logic.Inp_LOTO:=							Inp_LOTO; // Lock Out Tag Out (Servicebryter)
FB_VFD_Logic.Inp_Online:=							Inp_Online;
FB_VFD_Logic.Inp_Ready:=							Inp_Ready;
FB_VFD_Logic.Inp_RunningFwd:=					Wrk_Running;
FB_VFD_Logic.Inp_RunningRev :=					FALSE;
FB_VFD_Logic.Inp_Error:=								Inp_Fault;
FB_VFD_Logic.Inp_AutoRunFwd:=				Inp_AutoRunFwd;
FB_VFD_Logic.Inp_AutoSpeedRef:=				Inp_AutoSpeedRef;
FB_VFD_Logic.Inp_Warning:=						FALSE;
FB_VFD_Logic.Inp_Remote:=							TRUE;
FB_VFD_Logic.Inp_VoltageEnabled:=			TRUE;
FB_VFD_Logic.Inp_LocalStop	:=						FALSE;
FB_VFD_Logic.Inp_ComFault:=						FALSE;
FB_VFD_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_VFD_Logic.Inp_AlmSuppressDesc:= 		Inp_AlmSuppressDesc;

// Simulation logic data
//------------------------

Wrk_Running := FB_VFD_Logic.Out_RunFwd AND Inp_Ready; // Run Fwd

Wrk_SpeedRef := REAL_TO_UINT(ScaleTrans(
												  SclIn:=FB_VFD_Logic.Out_SpeedRef,
												  X0:=0.0,
												  Y0:=0.0,
												  X1:=100.0,
												  Y1:=Cfg_MaxSpeed));

IF Wrk_Running THEN
	// Ramp tilbakemelding
	IF Wrk_ActualSpeed < Wrk_SpeedRef THEN
		Wrk_ActualSpeed := Wrk_ActualSpeed + (Cfg_MaxSpeed * Wrk_IntervalSec) / Cfg_AccelerationTime;
		IF Wrk_ActualSpeed > Wrk_SpeedRef THEN
			Wrk_ActualSpeed := Wrk_SpeedRef;
		END_IF;
		
	ELSIF Wrk_ActualSpeed > Wrk_SpeedRef THEN
		Wrk_ActualSpeed := Wrk_ActualSpeed - (Cfg_MaxSpeed * Wrk_IntervalSec) / Cfg_AccelerationTime;
		IF Wrk_ActualSpeed < Wrk_SpeedRef THEN
			Wrk_ActualSpeed := Wrk_SpeedRef;
		END_IF;
	END_IF;
	
ELSIF Inp_Ready THEN
	Wrk_ActualSpeed := Wrk_ActualSpeed - (Cfg_MaxSpeed * Wrk_IntervalSec) / Cfg_AccelerationTime;
	
ELSE
	Wrk_ActualSpeed :=0.0;
END_IF;

// Begrens tilbakemelding
IF Wrk_ActualSpeed > Cfg_MaxSpeed THEN
	Wrk_ActualSpeed := Cfg_MaxSpeed;
ELSIF Wrk_ActualSpeed < 0.0 THEN
	Wrk_ActualSpeed := 0.0;
END_IF;

FB_VFD_Logic.Inp_ActSpeed := ScaleTrans(
											   		SclIn:=Wrk_ActualSpeed,
												  	X0:=0.0,
												  	Y0:=0.0,
												  	X1:=Cfg_MaxSpeed,
												  	Y1:=100.0);

(*************************************************************************
 *	Runtime
 *************************************************************************)

	IF FB_VFD_Logic.Inp_RunningFwd THEN
			Wrk_Runtime := ADD_TIME(Wrk_Runtime, GetMyTaskInterval()); 
	END_IF;
	
(*************************************************************************
 *	Execute VFD Logic
 *************************************************************************)
 
FB_VFD_Logic(Ext_VFD:=Ext_VFD, 
							Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	Update OUTPUT
 *************************************************************************)

//Block
Sts_AvailableAuto:=FB_VFD_Logic.Sts_AvailableAuto;
Sts_Alarm:=				FB_VFD_Logic.Sts_AlarmTriggered;

//Structure
Ext_VFD.EXT_Operator.Actual_State :='Hello';
Ext_VFD.EXT_Operator.Active_Error:='World!';
Ext_VFD.EXT_Statistics.Runtime_VFD := LINT_TO_UDINT( TimeToSec(Wrk_Runtime) / 3600);
